type Label = record(text: str, width: int)
type Align = enum(Left, Right)

fn format_label(label: Label, align: Align) -> str
    let t = trim(label.text)
    if len(t) >= label.width
        return t
    let pad = repeat(" ", label.width - len(t))
    if align == Align.Left
        return join([t, pad], "")
    else
        return join([pad, t], "")

fn initials(name: str) -> str =
    name |> trim |> words |> map(w => w |> chars |> first |> to_str |> upper) |> join("")

fn reverse_text(s: str) -> str =
    s |> chars |> reverse |> join("")

fn is_palindrome(s: str) -> bool
    let norm = s |> lower |> replace(" ", "")
    return norm == (norm |> chars |> reverse |> join(""))

type TextInfo = record(original: str, cleaned: str, length: int, reversed: str)

fn clean(s: str) -> str =
    s |> trim |> lower

fn reverse_str(s: str) -> str =
    s |> chars |> reverse |> join("")

fn summarize(s: str) -> TextInfo
    let c = clean(s)
    return TextInfo(s, c, len(c), reverse_str(c))

type PadSpec = record(left: bool, width: int)

fn pad_left(s: str, width: int) -> str = if len(s) >= width then s else join([repeat(" ", width - len(s)), s], "")

fn pad_right(s: str, width: int) -> str = if len(s) >= width then s else join([s, repeat(" ", width - len(s))], "")

fn pad(s: str, spec: PadSpec) -> str = if spec.left then pad_left(s, spec.width) else pad_right(s, spec.width)

fn reverse_str(s: str) -> str = s |> chars |> reverse |> join("")

type TextStats = record(original: str, trimmed: str, length: int, upper: str, reversed: str)

fn analyze(s: str) -> TextStats
    let t = trim(s)
    return TextStats(s, t, len(t), upper(t), reverse_str(t))

fn capitalize_word(w: str) -> str
    let head = upper(to_str(first(chars(w))))
    let tail = lower(join(skip(chars(w), 1), ""))
    return "{head}{tail}"

fn title_case(s: str) -> str = words(trim(s)) |> map(w => capitalize_word(w)) |> join(" ")

type WordStats = record(word: str, length: int, vowels: int)
fn analyze(word: str) -> WordStats
    let w = lower(trim(word))
    let vowels = chars(w) |> sum(c => if has("aeiou", to_str(c)) then 1 else 0)
    return WordStats(w, len(w), vowels)

type TextInfo = record(original: str, trimmed: str, length: int, reversed: str)
fn reverse_text(s: str) -> str = join(reverse(chars(s)), "")
fn inspect(s: str) -> TextInfo
    let t = trim(s)
    return TextInfo(s, t, len(t), reverse_text(t))

type NameParts = record(first: str, last: str)
fn split_name(full: str) -> NameParts
    let ws = words(trim(full))
    if len(ws) == 0
        return NameParts("", "")
    let f = first(ws)
    let l = if len(ws) == 1 then "" else last(ws)
    return NameParts(f, l)

fn initials(p: NameParts) -> str
    let a = if p.first == "" then "" else upper(to_str(first(chars(p.first))))
    let b = if p.last == "" then "" else upper(to_str(first(chars(p.last))))
    return "{a}{b}"

fn format_name(p: NameParts) -> str
    if p.last == ""
        return p.first
    else
        return "{p.last}, {p.first}"

fn pad_left(s: str, width: int, fill: str) -> str =
    if len(s) >= width then s else "{repeat(fill, width - len(s))}{s}"

fn pad_right(s: str, width: int, fill: str) -> str =
    if len(s) >= width then s else "{s}{repeat(fill, width - len(s))}"

type TextStats = record(original: str, trimmed: str, upper: str, reversed: str, length: int)

fn reverse_text(s: str) -> str =
    join(reverse(chars(s)), "")

fn analyze(s: str) -> TextStats =
