fn factorial(n: int) -> int =
    if n <= 1 then 1 else n * factorial(n - 1)

fn choose(n: int, k: int) -> int =
    factorial(n) / (factorial(k) * factorial(n - k))

type NumberInfo = record(n: int, digit_sum: int, prime: bool)

fn sum_digits(n: int) -> int
    let mut x = abs(n)
    let mut total = 0
    while x > 0
        total += x % 10
        x = x / 10
    return total

fn is_prime(n: int) -> bool =
    if n < 2 then false else all(range(2, n), d => n % d != 0)

fn describe_number(n: int) -> NumberInfo =
    NumberInfo(n, sum_digits(n), is_prime(n))

fn capitalize_word(w: str) -> str =
    if len(w) == 0 then "" else join([upper(join(take(w, 1), "")), lower(join(skip(w, 1), ""))], "")

fn capitalize_words(s: str) -> str =
    words(s) |> map(capitalize_word) |> join(" ")

type WordStats = record(count: int, longest: str, average_len: dec)

fn word_stats(s: str) -> WordStats
    let ws = words(s)
    if len(ws) == 0
        return WordStats(0, "", 0.0)
    let total_chars = sum(ws, w => len(w))
    let avg = dec(total_chars) / dec(len(ws))
    let sorted = sort_by_desc(ws, w => len(w))
    return WordStats(len(ws), first(sorted), avg)

type AcronymCase = enum(Upper, Lower)

fn acronym_case(s: str, c: AcronymCase) -> str
    let initials = words(s) |> map(w => join(take(w, 1), ""))
    if c == AcronymCase.Upper
        return initials |> map(x => upper(x)) |> join("")
    else
        return initials |> map(x => lower(x)) |> join("")

fn gcd(a: int, b: int) -> int
    let mut x = abs(a)
    let mut y = abs(b)
    let mut t = 0
    while not (y == 0)
        t = x % y
        x = y
        y = t
    return x

