type Longest = record(word: str, length: int)

fn longest_word_info(s: str) -> Longest
    let ws = words(s)
    if len(ws) == 0
        return Longest("", 0)
    let w = ws |> sort_by_desc(x => len(x)) |> first
    return Longest(w, len(w))

tests:
test "longest_word_info returns word and length"
    let empty = longest_word_info("")
    expect empty.word == ""
    expect empty.length == 0
    let info = longest_word_info("a bb ccc")
    expect info.word == "ccc"
    expect info.length == 3
    let tie = longest_word_info("one three seven")
    expect tie.word == "three"
    expect tie.length == 5

