type Sale = record(amount: dec, region: str)

fn total_sales(sales: list<Sale>) -> dec =
    sales |> sum(s => s.amount)

fn best_region(sales: list<Sale>) -> str?
    if len(sales) == 0
        return none
    let groups = group_by(sales, s => s.region)
    return max_by(keys(groups), r => sum(get(groups, r, list<Sale>()), s => s.amount))

tests:
test "Sale totals and best region"
    let s1 = Sale(10.0, "north")
    let s2 = Sale(20.0, "south")
    let s3 = Sale(15.0, "north")
    expect total_sales([]) == 0.0
    expect total_sales([s1, s2, s3]) == 45.0
    expect best_region([]) == none
    expect best_region([s1, s2, s3]) == "north"
    expect best_region([s2, Sale(15.0, "south")]) == "south"

