type Temperature = record(value: dec, unit: str)

fn to_celsius(t: Temperature) -> dec =
    if t.unit == "C" then t.value else (t.value - 32.0) * 5.0 / 9.0

fn to_fahrenheit(t: Temperature) -> dec =
    if t.unit == "F" then t.value else (t.value * 9.0 / 5.0) + 32.0

