fn f_to_c(f: dec) -> dec =
    (f - 32.0) * 5.0 / 9.0

fn convert_temp(value: dec, to_fahrenheit: bool) -> dec =
    if to_fahrenheit then c_to_f(value) else f_to_c(value)

type Trip = record(distance_km: dec, temp_c: dec)

fn distance_miles(t: Trip) -> dec =
    t.distance_km * 0.621371

fn temp_fahrenheit(t: Trip) -> dec =
    t.temp_c * 9.0 / 5.0 + 32.0

fn summary(t: Trip) -> str =
    "{round(distance_miles(t), 1)} mi, {round(temp_fahrenheit(t), 1)} F"

type Rule = record(word: str, divisor: int)

fn apply_rules(n: int, rules: list<Rule>) -> str
    let matching = rules |> filter(r => n % r.divisor == 0) |> map(r => r.word)
    if len(matching) == 0
        return to_str(n)
    else
        return matching |> join("")

type Rule = record(divisor: int, label: str)

fn apply_rules(n: int, rules: list<Rule>) -> str
    let matches = rules |> filter(r => n % r.divisor == 0) |> map(r => r.label)
    if len(matches) == 0
        return to_str(n)
    else
        return join(matches, "")

