fn valid_password(s: str) -> bool
    let len_ok = len(s) >= 8
    let has_upper = chars(s) |> any(c => has("ABCDEFGHIJKLMNOPQRSTUVWXYZ", to_str(c)))
    let has_lower = chars(s) |> any(c => has("abcdefghijklmnopqrstuvwxyz", to_str(c)))
    let has_digit = chars(s) |> any(c => has("0123456789", to_str(c)))
    return len_ok and has_upper and has_lower and has_digit

fn valid_email(s: str) -> bool
    if has(s, " ")
        return false
    let parts = split(s, "@")
    if len(parts) != 2
        return false
    let local = first(parts)
    let domain = last(parts)
    return len(local) > 0 and len(domain) > 2 and has(domain, ".") and not (starts(domain, ".")) and not (ends(domain, "."))

