type EmailCheck = record(ok: bool, message: str)

fn check_email(s: str) -> EmailCheck
    if has(s, " ")
        return EmailCheck(false, "no spaces")
    let parts = split(s, "@")
    if len(parts) != 2
        return EmailCheck(false, "one @ required")
    let local = first(parts)
    let domain = last(parts)
    if len(local) == 0
        return EmailCheck(false, "local part required")
    if not (has(domain, "."))
        return EmailCheck(false, "domain needs dot")
    if starts(domain, ".") or ends(domain, ".")
        return EmailCheck(false, "bad domain")
    return EmailCheck(true, "ok")

fn starts_with_letter(s: str) -> bool
    if len(s) == 0
        return false
    let c = first(chars(s))
    return has("abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ", to_str(c))

fn is_alphanumeric_or_underscore(s: str) -> bool
    return chars(s) |> all(c => has("abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789_", to_str(c)))

fn valid_username(s: str) -> bool
    return len(s) >= 3 and len(s) <= 15 and starts_with_letter(s) and is_alphanumeric_or_underscore(s)

