fn validate_code(code: str) -> CodeCheck
    if len(code) < 6
        return CodeCheck(false, "too short")
    if len(code) > 6
        return CodeCheck(false, "too long")
    if not (chars(code) |> all(c => has("ABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789", to_str(c))))
        return CodeCheck(false, "bad characters")
    return CodeCheck(true, "ok")

fn valid_password(s: str) -> bool
    let is_long = len(s) >= 8
    let has_upper = chars(s) |> any(c => has("ABCDEFGHIJKLMNOPQRSTUVWXYZ", to_str(c)))
    let has_lower = chars(s) |> any(c => has("abcdefghijklmnopqrstuvwxyz", to_str(c)))
    let has_digit = chars(s) |> any(c => has("0123456789", to_str(c)))
    return is_long and has_upper and has_lower and has_digit

