    return pw == confirm

fn validate_signup(password: str, confirm: str) -> str
    if not (passwords_match(password, confirm))
        return "passwords do not match"
    if not (valid_password(password))
        return "password too weak"
    return "ok"

fn valid_email(email: str) -> bool
    let parts = split(email, "@")
    return len(parts) == 2 and not has(email, " ") and len(first(parts)) > 0 and len(last(parts)) > 2 and has(last(parts), ".") and not starts(last(parts), ".") and not ends(last(parts), ".")

type PasswordCheck = record(ok: bool, message: str, score: int)

fn has_digit(s: str) -> bool =
    chars(s) |> any(c => (c >= '0' and c <= '9'))

fn has_upper(s: str) -> bool =
    chars(s) |> any(c => (c >= 'A' and c <= 'Z'))

fn assess_password(password: str) -> PasswordCheck
    let mut score = 0
    if len(password) >= 8
        score += 1
    if has_digit(password)
        score += 1
    if has_upper(password)
        score += 1
    if len(password) < 8
        return PasswordCheck(false, "too short", score)
    elif score < 2
        return PasswordCheck(false, "needs more variety", score)
    elif score == 2
        return PasswordCheck(true, "ok", score)
    else
        return PasswordCheck(true, "strong", score)

type EmailCheck = record(valid: bool, reason: str)

fn check_email(email: str) -> EmailCheck
    if len(email) == 0
        return EmailCheck(false, "empty")
