    grid[p.row][p.col]

fn in_bounds(grid: list<list<int>>, p: Point) -> bool =
    p.row >= 0 and p.row < len(grid) and p.col >= 0 and p.col < len(grid[p.row])

fn neighbor_sum(grid: list<list<int>>, p: Point) -> int
    let mut total = 0
    let up = Point(p.row - 1, p.col)
    if in_bounds(grid, up)
        total += value_at(grid, up)
    let down = Point(p.row + 1, p.col)
    if in_bounds(grid, down)
        total += value_at(grid, down)
    let left = Point(p.row, p.col - 1)
    if in_bounds(grid, left)
        total += value_at(grid, left)
    let right = Point(p.row, p.col + 1)
    if in_bounds(grid, right)
        total += value_at(grid, right)
    return total

