fn quartiles(xs: list<dec>) -> Quartiles
    if len(xs) == 0
        return Quartiles(0.0, 0.0, 0.0)
    let ys = sort(xs)
    let n = len(ys)
    let q2 = median(ys)
    if n == 1
        return Quartiles(q2, q2, q2)
    let half = n / 2
    let lower = ys |> take(half)
    let upper = ys |> skip(n - half)
    return Quartiles(median(lower), q2, median(upper))

