fn shift_char(c: char, n: int) -> str
    let lower = "abcdefghijklmnopqrstuvwxyz"
    let upper = "ABCDEFGHIJKLMNOPQRSTUVWXYZ"
    let shift = ((n % 26) + 26) % 26
    let t = to_str(c)
    let li = lower.IndexOf(t)
    if li >= 0
        return lower.Substring((li + shift) % 26, 1)
    let ui = upper.IndexOf(t)
    if ui >= 0
        return upper.Substring((ui + shift) % 26, 1)
    return t

fn caesar(s: str, shift: int) -> str =
    chars(s) |> map(c => shift_char(c, shift)) |> join("")

