fn caesar_decode(s: str, shift: int) -> str =
    caesar(s, -shift)

fn rle_decode(s: str) -> str
    let mut out = ""
    let mut last = ""
    for c in chars(s)
        let t = to_str(c)
        if has("0123456789", t)
            out += repeat(last, to_int(t))
        else
            last = t
    return out

type VowelMode = enum(Remove, Mask)
fn encode_char(c: char, mode: VowelMode) -> str
    let t = to_str(c)
    if not (has("aeiouAEIOU", t))
        return t
    return when mode
        VowelMode.Remove -> ""
        else -> "*"

fn encode_vowels(s: str, mode: VowelMode) -> str =
    chars(s) |> map(c => encode_char(c, mode)) |> join("")

