fn rle_decode(s: str) -> str
    let cs = chars(s)
    let mut out = ""
    let mut i = 0
    while i < len(cs)
        let c = first(skip(cs, i))
        let n = to_int(to_str(first(skip(cs, i + 1))))
        out += repeat(to_str(c), n)
        i += 2
