fn caesar_shift(s: str, n: int) -> str
    let lower = "abcdefghijklmnopqrstuvwxyz"
    let upper = "ABCDEFGHIJKLMNOPQRSTUVWXYZ"
    let shift = ((n % 26) + 26) % 26
    let out: list<str> = []
    for c in chars(s)
        let ch = to_str(c)
        if has(lower, ch)
            let idx = lower.IndexOf(ch)
            push(out, lower.Substring((idx + shift) % 26, 1))
        elif has(upper, ch)
            let idx = upper.IndexOf(ch)
            push(out, upper.Substring((idx + shift) % 26, 1))
        else
            push(out, ch)
    return join(out, "")

fn atbash(s: str) -> str
    let lower = "abcdefghijklmnopqrstuvwxyz"
    let upper = "ABCDEFGHIJKLMNOPQRSTUVWXYZ"
    let out: list<str> = []
    for c in chars(s)
        let ch = to_str(c)
        if has(lower, ch)
            let idx = lower.IndexOf(ch)
            push(out, lower.Substring(25 - idx, 1))
        elif has(upper, ch)
            let idx = upper.IndexOf(ch)
            push(out, upper.Substring(25 - idx, 1))
        else
            push(out, ch)
    return join(out, "")

