fn winner(votes: list<str>) -> str?
    let names = distinct(votes)
    if len(names) == 0
        return none
    let best = names |> max_by(n => count(votes, v => v == n))
    let top = count(votes, v => v == best)
    if count(names, n => count(votes, v => v == n) == top) > 1
        return none
    return best

fn percentages(votes: list<str>) -> map<str, dec>
    let total = len(votes)
    let out: map<str, dec> = map<str, dec>()
    if total == 0
        return out
    let names = distinct(votes)
    for n in names
        let pct = round(dec(count(votes, v => v == n)) * 100.0 / dec(total), 2)
        out[n] = pct
    return out

fn tied(votes: list<str>) -> list<str>
    let names = distinct(votes)
    if len(names) == 0
        return list<str>()
    let top = names |> map(n => count(votes, v => v == n)) |> max_of
    return names |> filter(n => count(votes, v => v == n) == top) |> sort

type Party = enum(Red, Blue, Green)

fn winning_party(votes: list<Party>) -> Party?
    if len(votes) == 0
        return none
    let parties = distinct(votes)
    let best = parties |> max_by(p => count(votes, v => v == p))
    let top = count(votes, v => v == best)
    if count(parties, p => count(votes, v => v == p) == top) > 1
        return none
    return best

fn vote_share(votes: list<str>, name: str) -> dec
