fn transpose(m: list<list<int>>) -> list<list<int>>
    if len(m) == 0
        return list<list<int>>()
    let cols = len(first(m))
    return range(0, cols) |> map(c => m |> map(row => first(skip(row, c))))

fn diagonal_sum(m: list<list<int>>) -> int
    if len(m) == 0
        return 0
    let n = min(len(m), len(first(m)))
    return range(0, n) |> sum(i => first(skip(first(skip(m, i)), i)))

fn anti_diagonal_sum(m: list<list<int>>) -> int
    let n = len(m)
    return range(0, n) |> sum(i => first(skip(first(skip(m, i)), n - 1 - i)))

