    if col < 0 or col >= len(grid[row])
        return fallback
    return grid[row][col]

type IntStack = record(items: list<int>, size: int)
type PopResult = record(value: int, rest: IntStack)

fn push_stack(s: IntStack, x: int) -> IntStack
    let out = s.items |> map(v => v)
    push(out, x)
    return IntStack(out, s.size + 1)

fn pop_stack(s: IntStack) -> PopResult
    if s.size == 0
        fail "empty stack"
    let v = last(s.items)
    let rest_items = take(s.items, s.size - 1)
    return PopResult(v, IntStack(rest_items, s.size - 1))

fn peek_stack(s: IntStack) -> int
    if s.size == 0
        fail "empty stack"
    return last(s.items)

